=== FILE: tb/crc8_block_tb.v ===
// Constrained-random, self-checking testbench for crc8_block.
// Requirement: Verify the existing CRC block RTL with constrained-random stimulus.
// Reference model written from interface_spec.md sections 2.1-2.3, not from the RTL.
// Inputs are driven at the falling edge; outputs are sampled 1 ns after each edge.
`timescale 1ns / 1ps
module crc8_block_tb;
    reg        clk   = 1'b0;
    reg        rst_n = 1'b0;
    reg        init  = 1'b0;
    reg        valid = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire [7:0] crc;

    crc8_block dut (
        .clk   (clk),
        .rst_n (rst_n),
        .init  (init),
        .valid (valid),
        .data  (data),
        .crc   (crc)
    );

    always #5 clk = ~clk;

    // Knobs
    localparam [31:0] SEED     = 32'h5EEDC8C8;
    localparam integer CYCLES_A = 4000;  // dense reloads: init 1/16, reset 1/64
    localparam integer CYCLES_B = 4000;  // sparse reloads: init 1/256, reset 1/512

    reg [31:0]     rng;
    reg [7:0]      model;     // the spec's running value
    reg            armed;
    integer        passed, failed;
    integer        n_bytes, n_init_valid, n_rst_valid, n_hold, n_reload;
    integer        n_long, frame_len, n_d00, n_dff, n_d80, n_d01;
    integer        cyc;
    reg [8*64-1:0] nonce;
    reg            have_nonce;
    reg            r_r, r_i, r_v, phase_b;
    reg [7:0]      r_d;

    // Spec 2.2: for each bit 7..0, XOR it into the top bit, shift left,
    // and if the bit shifted out is 1, reduce by x^8 + x^2 + x + 1 (9'h107).
    function [7:0] spec_take(input [7:0] run, input [7:0] b);
        reg [8:0] w;
        integer k;
        begin
            w = {1'b0, run};
            for (k = 7; k >= 0; k = k - 1) begin
                w[7] = w[7] ^ b[k];
                w = w << 1;
                if (w[8])
                    w = w ^ 9'h107;
            end
            spec_take = w[7:0];
        end
    endfunction

    task next_rng;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    task check(input [7:0] got, input [7:0] exp, input [8*48-1:0] what);
        begin
            if (got === exp)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                if (failed <= 20)
                    $display("MISMATCH t=%0t %0s: got=%h expected=%h (rst_n=%b init=%b valid=%b data=%h)",
                             $time, what, got, exp, rst_n, init, valid, data);
            end
        end
    endtask

    task cover_check(input ok, input [8*48-1:0] what, input integer count);
        begin
            if (ok) begin
                passed = passed + 1;
                $display("COVER ok   %0s: %0d", what, count);
            end else begin
                failed = failed + 1;
                $display("COVER MISS %0s: %0d", what, count);
            end
        end
    endtask

    // Check the DUT and the model against a constant computed from the spec.
    task check_const(input [7:0] exp, input [8*48-1:0] what);
        begin
            check(crc, exp, what);
            check(model ^ 8'hFF, exp, "model vs hand-computed vector");
        end
    endtask

    task cycle(input r, input i, input v, input [7:0] d);
        begin
            @(negedge clk);
            rst_n = r; init = i; valid = v; data = d;
            // CRC-FINAL: crc follows the running value only, no edge yet.
            #1 if (armed) check(crc, model ^ 8'hFF, "no change before edge");
            @(posedge clk);
            // Model update, priority per spec 2.1/2.2.
            if (!r) begin
                model = 8'hFF;
            end else if (i) begin
                model = 8'hFF;
            end else if (v) begin
                model = spec_take(model, d);
            end
            // Corner bookkeeping.
            if (!r && v)       n_rst_valid  = n_rst_valid + 1;
            if (r && i && v)   n_init_valid = n_init_valid + 1;
            if (r && !i && !v) n_hold       = n_hold + 1;
            if (r && !i && v) begin
                n_bytes   = n_bytes + 1;
                frame_len = frame_len + 1;
                if (d == 8'h00) n_d00 = n_d00 + 1;
                if (d == 8'hFF) n_dff = n_dff + 1;
                if (d == 8'h80) n_d80 = n_d80 + 1;
                if (d == 8'h01) n_d01 = n_d01 + 1;
            end
            if (!r || i) begin
                n_reload = n_reload + 1;
                if (frame_len >= 16) n_long = n_long + 1;
                frame_len = 0;
            end
            #1 check(crc, model ^ 8'hFF, "after edge");
            armed = 1'b1;
        end
    endtask

    initial begin
        passed = 0; failed = 0; armed = 1'b0;
        n_bytes = 0; n_init_valid = 0; n_rst_valid = 0; n_hold = 0; n_reload = 0;
        n_long = 0; frame_len = 0; n_d00 = 0; n_dff = 0; n_d80 = 0; n_d01 = 0;
        model = 8'hFF;
        rng = SEED;

        have_nonce = 1'b1;
        if (!$value$plusargs("nonce=%s", nonce))
        if (!$value$plusargs("NONCE=%s", nonce))
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
        if (!$value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce))
            have_nonce = 1'b0;

        $display("crc8_block_tb: seed=%h cycles=%0d+%0d", SEED, CYCLES_A, CYCLES_B);

        // ---------------- Directed phase ----------------
        // CRC-RESET, CRC-EMPTY
        cycle(1'b0, 1'b0, 1'b0, 8'h00);
        check_const(8'h00, "CRC-EMPTY after reset");
        cycle(1'b0, 1'b1, 1'b1, 8'hA5);
        check_const(8'h00, "CRC-RESET with init and valid");
        // CRC-POLY: one byte 0x00 from start value
        cycle(1'b1, 1'b0, 1'b1, 8'h00);
        check_const(8'h0C, "byte 00 from FF");
        // CRC-HOLD: valid low, data moving
        cycle(1'b1, 1'b0, 1'b0, 8'h5A);
        cycle(1'b1, 1'b0, 1'b0, 8'hC3);
        check_const(8'h0C, "CRC-HOLD");
        // CRC-INIT reload
        cycle(1'b1, 1'b1, 1'b0, 8'h00);
        check_const(8'h00, "CRC-INIT reload");
        cycle(1'b1, 1'b0, 1'b1, 8'hFF);
        check_const(8'hFF, "byte FF from FF");
        cycle(1'b1, 1'b0, 1'b1, 8'h00);
        check_const(8'hFF, "byte 00 from 00");
        // CRC-INIT wins over a byte at the same edge
        cycle(1'b1, 1'b1, 1'b1, 8'h3C);
        check_const(8'h00, "CRC-INIT wins over valid");
        // CRC-ORDER: bit 7 first, no reflection
        cycle(1'b1, 1'b0, 1'b1, 8'h80);
        check_const(8'h85, "CRC-ORDER byte 80");
        cycle(1'b1, 1'b1, 1'b0, 8'h00);
        cycle(1'b1, 1'b0, 1'b1, 8'h01);
        check_const(8'h0B, "CRC-ORDER byte 01");
        // Reset mid-frame with a byte offered
        cycle(1'b1, 1'b0, 1'b1, 8'h77);
        cycle(1'b0, 1'b0, 1'b1, 8'h77);
        check_const(8'h00, "CRC-RESET wins over valid");
        cycle(1'b1, 1'b0, 1'b0, 8'h00);
        check_const(8'h00, "CRC-EMPTY hold after reset");

        // ---------------- Constrained-random phase ----------------
        for (cyc = 0; cyc < CYCLES_A + CYCLES_B; cyc = cyc + 1) begin
            phase_b = (cyc >= CYCLES_A);
            next_rng;
            r_r = phase_b ? (rng[8:0] != 9'd0)   : (rng[5:0] != 6'd0);
            r_i = phase_b ? (rng[19:12] == 8'd0) : (rng[15:12] == 4'd0);
            r_v = (rng[21:20] != 2'd0);
            case (rng[24:22])
                3'd0:    r_d = 8'h00;
                3'd1:    r_d = 8'hFF;
                3'd2:    r_d = rng[25] ? 8'h80 : 8'h01;
                default: begin next_rng; r_d = rng[7:0]; end
            endcase
            cycle(r_r, r_i, r_v, r_d);
        end

        // ---------------- Coverage closure ----------------
        cover_check(n_bytes      >= 4000, "bytes taken",              n_bytes);
        cover_check(n_init_valid >= 50,   "init with valid same edge", n_init_valid);
        cover_check(n_rst_valid  >= 10,   "reset with valid same edge", n_rst_valid);
        cover_check(n_hold       >= 500,  "hold cycles",              n_hold);
        cover_check(n_reload     >= 100,  "reloads",                  n_reload);
        cover_check(n_long       >= 5,    "frames of 16+ bytes",      n_long);
        cover_check(n_d00        >= 100,  "byte 00 taken",            n_d00);
        cover_check(n_dff        >= 100,  "byte FF taken",            n_dff);
        cover_check(n_d80        >= 20,   "byte 80 taken",            n_d80);
        cover_check(n_d01        >= 20,   "byte 01 taken",            n_d01);

        if (!have_nonce) begin
            failed = failed + 1;
            nonce = "missing";
            $display("ERROR: no nonce plusarg found");
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
